  protected async statement(p: Person): Promise<void> {
    this.rowErrors.update(({ [p.id]: _, ...rest }) => rest);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    try {
      const taken = await this.api.statement(sheetId, p.id);
      if (this.session.sheetId() !== sheetId) return;
      this.taken(taken.person);
      this.claims.update((cs) => [...cs.filter((c) => c.personId !== p.id), ...taken.claims].sort((a, b) => b.id - a.id));
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [p.id]: statementError(e) }));
    }
  }

  /** Retire a person from a date (blank: the sheet's today); the row then shows them retired. */
  protected async retire(p: Person, from: string): Promise<void> {
    this.clearRowError(p.id);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    try {
      const retired = await this.api.retire(sheetId, p.id, from.trim());
      if (this.session.sheetId() === sheetId) this.taken(retired);
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [p.id]: retireError(e) }));
    }
  }

  /** Put a person on hold, or take them off it when held; the row then shows the new state. */
  protected async hold(p: Person): Promise<void> {
    this.clearRowError(p.id);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    try {
      const saved = await this.api.hold(sheetId, p.id, !p.held);
      if (this.session.sheetId() === sheetId) this.taken(saved);
    } catch (e) {
      this.rowErrors.update((errs) => ({ ...errs, [p.id]: holdError(e) }));
    }
  }

  protected clearRowError(id: number): void {
    this.rowErrors.update(({ [id]: _, ...rest }) => rest);
  }

  /** Take in a rate just set, in place of the grade's old one for the same from-date. */
  protected rateSaved(rate: Rate): void {
    this.rates.update((rs) => [...rs.filter((r) => r.grade !== rate.grade || r.from !== rate.from), rate]);
  }

  /** Take in a period just added or closed, in its place by from-date. */
  protected periodSaved(period: Period): void {
    this.periods.update((ps) => [...ps.filter((p) => p.id !== period.id), period].sort((a, b) => a.from.localeCompare(b.from)));
  }

  /** Take in a claim just added (listed first, as the newest) or saved (in its place). */
  protected claimSaved(claim: Claim): void {
    this.claims.update((cs) => cs.some((c) => c.id === claim.id)
      ? cs.map((c) => (c.id === claim.id ? claim : c))
      : [claim, ...cs].sort((a, b) => b.id - a.id));
  }

  protected cancel(): void {
    this.reset();
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const value = this.form.getRawValue();
    if (!value.name.trim()) {
      this.error.set('Enter a name.');
      return;
    }
    if (!(GRADES as readonly string[]).includes(value.grade)) {
      this.error.set('Choose a grade.');
      return;
    }
    const editing = this.editingId();
    this.submitting = true;
    try {
      if (editing === null) {
        const added = await this.api.add(sheetId, value);
        if (this.session.sheetId() === sheetId) this.people.update((ps) => [...ps, added]);
      } else {
        const saved = await this.api.update(sheetId, editing, { ...value, version: this.editingVersion });
        if (this.session.sheetId() === sheetId) this.taken(saved);
      }
      this.reset();
    } catch (e) {
      if (editing !== null && isStale(e)) await this.reloadEditing(sheetId, editing);
      this.error.set(personError(e));
    } finally {
      this.submitting = false;
    }
  }

  /** Quick-add a DRAFT claim by name; the person is added first (grade A) when new. */
  protected async quickAdd(): Promise<void> {
    if (this.quickAdding) return;
    this.quickError.set(null);
    const sheetId = this.session.sheetId();
    if (!sheetId) return;
    const value = this.quickForm.getRawValue();
    const amount = value.amount.trim();
    if (!value.name.trim()) {
      this.quickError.set('Enter a name.');
      return;
    }
    if (!AMOUNT_PATTERN.test(amount)) {
      this.quickError.set('Enter an amount of 0.00 or more with up to two decimals.');
      return;
    }
    this.quickAdding = true;
    try {
      const added = await this.claimsApi.quickAdd(sheetId, { name: value.name, amount });
      if (this.session.sheetId() !== sheetId) return;
      if (added.personAdded) this.people.update((ps) => [...ps.filter((p) => p.id !== added.person.id), added.person]);
      else this.taken(added.person);
      this.claimSaved(added.claim);
      this.quickForm.reset({ name: '', amount: '' }, { emitEvent: false });
    } catch (e) {
      this.quickError.set(quickAddError(e));
    } finally {
      this.quickAdding = false;
    }
  }

  /** Take in a person as the store now holds them, in place of the old row. */
  private taken(person: Person): void {
    this.people.update((ps) => ps.map((p) => (p.id === person.id ? person : p)));
  }

  /** After a save refused as stale, show the person's current values in the row and the open
   *  editor, which then edits that version. */
  private async reloadEditing(sheetId: string, id: number): Promise<void> {
    try {
      const current = await this.api.get(sheetId, id);
      if (this.session.sheetId() !== sheetId || this.editingId() !== id) return;
      this.taken(current);
      this.editingVersion = current.version;
      this.form.setValue({ name: current.name, grade: current.grade }, { emitEvent: false });
    } catch {
      // the error shown already says the save was refused
    }
  }

  private reset(): void {
    this.editingId.set(null);
    this.form.reset({ name: '', grade: 'A' });
    this.error.set(null);
  }

  private async read(sheetId: string): Promise<void> {
    const seq = ++this.readSeq;
    try {
      const [people, claims, rates, periods] = await Promise.all([
        this.api.list(sheetId), this.claimsApi.list(sheetId), this.ratesApi.list(sheetId), this.periodsApi.list(sheetId)]);
      if (seq === this.readSeq) {
        this.rates.set(rates);
        this.periods.set(periods);
        this.claims.set(claims);
        this.people.set(people);
      }
    } catch {
      if (seq === this.readSeq) this.error.set('Something went wrong loading people; try again.');
    }
  }
}
import { HttpClient, HttpErrorResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Session } from '../../core/session';
import { Claim } from '../claims/claims-api';

export const GRADES = ['A', 'B', 'C'] as const;

export interface Person {
  id: number;
  name: string;
  grade: string;
  /** Raised on every save. */
  version: number;
  /** How many statements have been taken of the person. */
  statementCount: number;
  /** The last statement's due-total, with two decimals; null when it was n/a or there is none. */
  statedTotal: string | null;
  /** The sheet's today when the last statement was taken; null with none. */
  statementDate: string | null;
  /** The date the person is retired from; null while not retired. Set, they count as retired. */
  retiredFrom: string | null;
  /** Whether the person is on hold: their OPEN claims then count in no live total. */
  held: boolean;
}

/** A statement just taken: the person as they now show, and all their claims, newest first. */
export interface Statement {
  person: Person;
  claims: Claim[];
}

export interface PersonForm {
  name: string;
  grade: string;
  /** On an edit, the version of the person the editor loaded. */
  version?: number;
}

// The people kept on the active sheet, read and written through the server.
@Injectable({ providedIn: 'root' })
export class PeopleApi {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);

  list(sheetId: string): Promise<Person[]> {
    return firstValueFrom(this.http.get<Person[]>(this.url(sheetId), { headers: this.headers() }));
  }

  add(sheetId: string, form: PersonForm): Promise<Person> {
    return firstValueFrom(this.http.post<Person>(this.url(sheetId), form, { headers: this.headers() }));
  }

  get(sheetId: string, id: number): Promise<Person> {
    return firstValueFrom(this.http.get<Person>(`${this.url(sheetId)}/${id}`, { headers: this.headers() }));
  }

  update(sheetId: string, id: number, form: PersonForm): Promise<Person> {
    return firstValueFrom(this.http.put<Person>(`${this.url(sheetId)}/${id}`, form, { headers: this.headers() }));
  }

  /** Take a statement of a person, binding their counting claims to the dues they show now. */
  statement(sheetId: string, id: number): Promise<Statement> {
    return firstValueFrom(
      this.http.post<Statement>(`/api/sheets/${encodeURIComponent(sheetId)}/people/${id}/statement`, null,
        { headers: this.headers() }),
    );
  }

  /** Retire a person from a date; a blank one takes the sheet's today. */
  retire(sheetId: string, id: number, from: string): Promise<Person> {
    return firstValueFrom(
      this.http.post<Person>(`${this.url(sheetId)}/${id}/retire`, { from: from || null }, { headers: this.headers() }),
    );
  }

  /** Put a person on hold (true) or take them off it (false). */
  hold(sheetId: string, id: number, held: boolean): Promise<Person> {
    return firstValueFrom(
      this.http.post<Person>(`${this.url(sheetId)}/${id}/hold`, { held }, { headers: this.headers() }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/people`;
  }

  private headers(): Record<string, string> {
    return { 'X-User': this.session.user() ?? '' };
  }
}

export function personError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a name and choose a grade.';
  if (isStale(e)) return 'Someone else saved this person since you opened it; the form now shows their values.';
  if (e instanceof HttpErrorResponse && e.status === 409) return 'That name is already in use on this sheet.';
  return 'Something went wrong; try again.';
}

export function statementError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That person is no longer on this sheet.';
  return 'Something went wrong; try again.';
}

export function retireError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 400) return 'Enter a date as yyyy-mm-dd.';
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That person is no longer on this sheet.';
  return 'Something went wrong; try again.';
}

export function holdError(e: unknown): string {
  if (e instanceof HttpErrorResponse && e.status === 404) return 'That person is no longer on this sheet.';
  return 'Something went wrong; try again.';
}

/** Whether a save was refused because someone else saved the person since the editor loaded it. */
export function isStale(e: unknown): boolean {
  return e instanceof HttpErrorResponse && e.status === 412;
}
